    "sx.f_majors": { en: "Majors" },
    "sx.f_alts": { en: "Alts" },
    "sx.f_stables": { en: "Stables" },
    "sx.disc": { en: "This is a <b>digital twin</b>: a deterministic simulation of a hypothetical portfolio under price shocks. Liquidation is modelled per isolated-margin leg (a leg is liquidated when its loss reaches its margin). It is <b>not</b> a prediction, not your real account, and not investment advice — real liquidations depend on your venue’s exact maintenance margin, funding and slippage. Build your real safety envelope in the <a href=\"/dashboard#agents\">app</a>." },
    "pv.nav_roots": { en: "Daily roots" },
    "pv.nav_raw": { en: "Raw feed" },
    "pv.h1": { en: "🔏 Verify it yourself" },
    "pv.lede": { en: "This page is the complete, self-contained verification contract for RUNECLAW’s Provable Calls. You need nothing from us but public URLs — no account, no API key, no trust. If any check on this page ever fails, the receipt is broken and you should say so loudly." },
    "pv.s1_h": { en: "1 · What gets sealed, and when" },
    "pv.s1_p": { en: "The moment the engine publishes a trading call — and the moment any Arena paper trade fills — the decision facts are serialized to a canonical JSON string and hashed with SHA-256. That hash is the <b>seal</b>. Outcomes attach to the same record later and mathematically cannot move the seal. A call that was edited, backdated, or invented after the fact cannot produce a matching hash." },
    "pv.c_v1_t": { en: "Canonical payload · v1 · engine signal" },
    "pv.c_v1_p": { en: "Key order is the contract. The served <code>seal_payload</code> is the exact sealed string — hash it verbatim, never re-serialize it." },
    "pv.c_v2_t": { en: "Canonical payload · v2 · arena paper trade" },
    "pv.c_v2_p": { en: "Sealed at open — before anyone knows how the trade ends. The payload carries prices, leverage and times only; virtual balances never appear on any public surface." },
    "pv.s2_h": { en: "2 · Verify one call" },
    "pv.s2_l1": { en: "Fetch <code>GET /api/call/&lt;key&gt;</code> (keys look like <code>sig:…</code> or <code>arena:…</code>)." },
    "pv.s2_l2": { en: "Compute <code>sha256(seal_payload)</code> over the served string, UTF-8, exactly as-is." },
    "pv.s2_l3": { en: "It must equal <code>seal</code>. Then compare the payload’s fields to <code>current</code> — any difference means the live record was rewritten after sealing." },
    "pv.s2_note": { en: "Every <code>/call/&lt;key&gt;</code> page runs the same math in your browser with WebCrypto — this snippet just proves you don’t need our page to do it." },
    "pv.s3_h": { en: "3 · Verify a whole day" },
    "pv.s3_p": { en: "At the end of each UTC day, every seal minted that day folds into one Merkle root, published at <a href=\"/api/roots\">/api/roots</a> (human view: <a href=\"/roots\">/roots</a>). The construction:" },
    "pv.s3_l1": { en: "Leaves = the day’s seals (64-char hex), deduplicated, sorted ascending." },
    "pv.s3_l2": { en: "Parent = <code>sha256(utf8(leftHex + rightHex))</code> — the two hex strings concatenated." },
    "pv.s3_l3": { en: "An unpaired last node is promoted unchanged. A single leaf is its own root." },
    "pv.s3_proof": { en: "Receipts from completed days carry <code>anchor.proof</code> — a list of <code>{pos, hash}</code> steps. Replay it:" },
    "pv.s5_h": { en: "5 · Read the rules, not the results" },
    "pv.s5_p": { en: "Everything above is written down in full, outside this page, so a checker can be built against a document rather than against our word: the <a href=\"https://github.com/metafrogmeme-droid/001/blob/main/docs/PROVABLE_CALLS_SPEC.md\" rel=\"noopener\">Provable Calls specification</a> gives the exact payloads, hash rule and root construction, and <a href=\"https://github.com/metafrogmeme-droid/001/blob/main/docs/ENGINEERING_STANDARD.md\" rel=\"noopener\">the engineering standard</a> states the one rule every number on this site is held to — and what it deliberately does <em>not</em> promise. Both are pinned by tests that fail if the code stops matching them." },
    "pv.s4_h": { en: "4 · Become a mirror" },
    "pv.s4_p": { en: "Copy any day’s root anywhere durable and public — a tweet, a git commit, a chain memo. From that moment the day is frozen for everyone: we cannot back-insert a call into it without changing the root you hold. One mirrored hash timestamps every call of the day. That’s the whole design: <b>don’t trust the screenshot — verify the call.</b>" },
    "pv.scope": { en: "<b>Honest scope:</b> a seal proves the decision facts existed unchanged since sealing; a root proves set membership for its day; a mirror makes the day independently timestamped. None of this proves future performance, and none of it is investment advice. Operator-published on-chain anchoring of the same roots is planned and will be stated on the verify pages when live — never before." },
