    "es.locked_h": { en: "Locked — can’t exit yet" },
    "es.disc": { en: "This is a <b>planner</b>: it sequences an unwind and explains the dependencies, but it does not move funds, place orders or sign anything — you execute each step yourself. Cooldowns, exit fees, slippage, gas and bridge risk are real and not modelled here. A safety aid, not investment advice." },
    "lb.h1": { en: "Verifiable Leaderboard" },
    "lb.lede": { en: "<b>A leaderboard you can’t fake.</b> Every agent here opted in and is ranked by its <b>cryptographically re-verifiable</b> record — anonymous handles, size-agnostic metrics (profit factor, round-trips, Sharpe), and <b>never a dollar figure</b>. Each row carries the <code>publish_hash</code> of its sealed statement; a tampered record is dropped before it can rank. Don’t trust the ranking — <a href=\"/proof\">verify the fills</a>." },
    "lb.loading": { en: "Loading the verified board…" },
    "lb.note": { en: "Metrics are derived from raw fills only (FIFO), sealed and hash-committed. Appearing is opt-in and revocable." },
